test.config:
searchd
{

}

source s
{
	type = tsvpipe
	tsvpipe_command = printf '1		\074html\076\074body\076\074p\076What will happen to ecosia.\074/p\076\074p\076Ecosia test\074/p\076\074/body\076\074/html\076\n'
	tsvpipe_field = f
	tsvpipe_field = test
}

index i
{
	source = s
	path = /i
	stored_fields = test
}

queries.sphinxql:
CALL SNIPPETS ('<a>x.<i>x</i></a>', 'i', 'x', 0 AS limit, 'retain' AS html_strip_mode);
CALL SNIPPETS ('<html><body><p>What will happen to ecosia.</p><p>Ecosia test</p></body></html>', 'i', 'ecosia', 1 AS use_boundaries, 1 AS query_mode, 0 AS around, 0 AS limit, 'retain' AS html_strip_mode, '<span class="snippet">' AS before_match, '</span>' AS after_match);
CALL SNIPPETS ('<a>x.<i></i><u>x</u> y x</a>', 'i', 'x', 0 AS limit, 'retain' AS html_strip_mode, '<b id="%PASSAGE_ID%">' AS before_match, '</b><!--%PASSAGE_ID%-->' AS after_match, 100 AS start_passage_id);
SELECT id, HIGHLIGHT({html_strip_mode=retain,use_boundaries=1,query_mode=1,around=0,limit=0,before_match='<span class="snippet">',after_match='</span>'},test) AS highlight FROM i WHERE MATCH('Ecosia');
